-- Columns/defaults from the user Supabase diagnostic, 2026-09-29.
create table public.generation_jobs (
  id uuid default gen_random_uuid() not null primary key,
  user_id uuid not null,
  user_email text,
  title text default 'Nova criação'::text not null,
  source_type text not null,
  status text default 'queued'::text not null,
  active_operation text,
  active_operation_id uuid,
  prompt text,
  refinement_text text,
  input_image_name text,
  input_image_type text,
  image_path text,
  rendered_image_path text,
  model_url text,
  tripo_task_id text,
  tripo_status text,
  progress smallint default 0 not null,
  retry_count integer default 0 not null,
  error_message text,
  metadata jsonb default '{}'::jsonb not null,
  operation_started_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  completed_at timestamp with time zone,
  model_path text
);
